export const tours = pgTable(
  'tours',
  {
    id: serial('id').primaryKey(),
    slug: varchar('slug'),
    price: numeric('price', { mode: 'number' }),
    currency: varchar('currency').default('MYR'),
    duration: varchar('duration'),
    durationMinutes: numeric('duration_minutes', { mode: 'number' }),
    location: varchar('location'),
    maxParticipants: numeric('max_participants', { mode: 'number' }),
    minParticipants: numeric('min_participants', { mode: 'number' }).default(2),
    tailoredAvailable: boolean('tailored_available').default(false),
    heroImage: integer('hero_image_id').references(() => media.id, {
      onDelete: 'set null',
    }),
    ticketingHubId: varchar('ticketing_hub_id'),
    isBookable: boolean('is_bookable').default(false),
    bookingUrl: varchar('booking_url'),
    instantConfirmation: boolean('instant_confirmation').default(true),
    scheduledPublish: timestamp('scheduled_publish', {
      mode: 'string',
      withTimezone: true,
      precision: 3,
    }),
    tourFrequency: varchar('tour_frequency'),
    dishesCount: numeric('dishes_count', { mode: 'number' }),
    difficulty: enum_tours_difficulty('difficulty').default('easy'),
    walkingDistance: varchar('walking_distance'),
    directionsHtml: varchar('directions_html'),
    promoVideoUrl: varchar('promo_video_url'),
    featured: boolean('featured').default(false),
    popular: boolean('popular').default(false),
    new: boolean('new').default(false),
    publishedAt: timestamp('published_at', { mode: 'string', withTimezone: true, precision: 3 }),
    status: enum_tours_status('status').default('draft'),
    workflowStatus: enum_tours_workflow_status('workflow_status').default('draft'),
    updatedAt: timestamp('updated_at', { mode: 'string', withTimezone: true, precision: 3 })
      .defaultNow()
      .notNull(),
    createdAt: timestamp('created_at', { mode: 'string', withTimezone: true, precision: 3 })
      .defaultNow()
      .notNull(),
    _status: enum_tours_status('_status').default('draft'),
  },
  (columns) => [
    uniqueIndex('tours_slug_idx').on(columns.slug),
    index('tours_hero_image_idx').on(columns.heroImage),
    index('tours_updated_at_idx').on(columns.updatedAt),
    index('tours_created_at_idx').on(columns.createdAt),
    index('tours__status_idx').on(columns._status),
  ],
)

